    /*
     * Assign a Employee
     * 
     * @param	parentId	UUID
     * @param	assignment 	Employee 
     * @return	TaxWithholding
     */
    public TaxWithholding assignEmployee( UUID parentId, Employee assignment ) {
	    LOGGER.info("assigning Employee as " + assignment.toString() );

	    TaxWithholding parentEntity = repository.findById( parentId ).get();
	    assignment = registry.project( Employee.class, assignment.getEmployeeId());

	    // ------------------------------------------
		// assign the Employee to the parent entity
		// ------------------------------------------ 
	    parentEntity.setEmployee( assignment );

	    // ------------------------------------------
    	// save the parent entity
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

	/*
	 * Unassign the Employee
	 * 
	 * @param	parentId		UUID
	 * @return	TaxWithholding
	 */
	public TaxWithholding unAssignEmployee( UUID parentId ) {
		TaxWithholding parentEntity = repository.findById(parentId).get();

		LOGGER.info("unAssigning Employee on " + parentEntity.toString() );
		
	    // ------------------------------------------
		// null out the Employee on the parent entithy
		// ------------------------------------------     
	    parentEntity.setEmployee(null);

	    // ------------------------------------------
		// save the parent entity
		// ------------------------------------------ 
	    repository.save(parentEntity);
    
	    return parentEntity;
	}




